import React, { useState } from 'react';
import {
  Button,
  Box,
  Text,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  useToast,
  Spinner
} from '@chakra-ui/react';
import { apiConfig, getCorsProxyUrl } from '../../../config/apiConfig';

export const TestConnection: React.FC = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [testResult, setTestResult] = useState<{
    success: boolean;
    message: string;
  } | null>(null);
  const toast = useToast();

  const testConnection = async () => {
    try {
      setIsLoading(true);
      setTestResult(null);
      
      // Test the n8n API connection using the health endpoint
      const baseUrl = apiConfig.n8nBaseUrl;
      let testUrl = `${baseUrl}/api/v1/health`;
      
      // Add API key as query parameter if needed
      if (apiConfig.apiKey) {
        testUrl += `?apiKey=${apiConfig.apiKey}`;
      }
      
      // Apply CORS proxy if needed
      const proxyUrl = getCorsProxyUrl(testUrl);
      
      console.log('Testing connection to n8n...', {
        baseUrl,
        testUrl,
        proxyUrl
      });
      
      const response = await fetch(proxyUrl, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
          'X-Requested-With': 'XMLHttpRequest',
          ...(apiConfig.apiKey && { 'X-N8N-API-KEY': apiConfig.apiKey }),
        }
      });
      
      // Get response data if possible
      let data;
      try {
        data = await response.json();
      } catch (e) {
        // If not JSON, use status text
        data = { message: response.statusText };
      }
      
      console.log('Test connection result:', {
        success: response.ok,
        status: response.status,
        data
      });
      
      if (response.ok) {
        setTestResult({
          success: true,
          message: 'Connection successful! n8n API is accessible.'
        });
      } else {
        setTestResult({
          success: false,
          message: `Connection failed: ${response.status} ${response.statusText}`
        });
      }
    } catch (error) {
      console.error('Error testing connection:', error);
      setTestResult({
        success: false,
        message: `Error: ${error instanceof Error ? error.message : String(error)}`
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Box mb={4}>
      <Button 
        colorScheme="blue" 
        onClick={testConnection} 
        isLoading={isLoading}
        loadingText="Testing"
        mb={4}
      >
        Test n8n Connection
      </Button>
      
      {testResult && (
        <Alert 
          status={testResult.success ? 'success' : 'error'}
          variant="subtle"
          flexDirection="column"
          alignItems="flex-start"
          borderRadius="md"
          p={4}
        >
          <AlertIcon />
          <AlertTitle mr={2}>
            {testResult.success ? 'Connection Successful' : 'Connection Failed'}
          </AlertTitle>
          <AlertDescription>
            {testResult.message}
            {!testResult.success && (
              <Text mt={2} fontSize="sm">
                Make sure your API key is correct and that your n8n instance is accessible.
              </Text>
            )}
          </AlertDescription>
        </Alert>
      )}
    </Box>
  );
}; 